        private void CollectBranch_LeavingEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            _Branch = _DataManipulatorTable.FormatData("F0006", "MCMCU", _CollectBranch.BranchPlantsTable.MCMCU);
            _TableFormattedBranchPlant = _DataManipulatorTable.FormatData("F0006", "MCMCU", _CollectBranch.BranchPlantsTable.MCMCU);
            _LicensePlateNumberingConstantsTable.BranchPlant = _Branch;
            if ((_LPLicense) && (_LicensePlateNumberingConstantsTable.IsLicensePlatingActive()))
            {
                Back(_CollectBranch);
                Error("LPBranch");
                return;
            }

            if (!_CycleHeaderTable.ShowOpenCounts(_TableFormattedBranchPlant, _StatusCodesAllowed))
            {
                Back(_CollectBranch);
                Error("NoCountsForBranch");
                return;
            }

            if (WFOptions.RetrieveOptionValue("CountType") == "6" || WFOptions.RetrieveOptionValue("CountType") == "7")
            {
                Next(_CollectLotNumber);
            }
            else
            {
                Next(_CollectCycleNumber);
            }
        }

