        #region ProcessVerifyLocationEnterKey

        private void ProcessVerifyLocationEnterKey(ScreenEventArgs e)
        {
            // location must be same as cycle count detail

            // validate the location
            _Location = EmptyStringCompatible(e.UserInput.ToString().ToUpper());
            _LocationMasterTable.ResetAll();
            _LocationMasterTable.MCU = _TableFormattedBranchPlant;
            _LocationMasterTable.inLOCN = _Location;
            if (_LocationMasterTable.ValidateLocation())
            {
                if (_CycleCountDetailTable.PJLOCN.Trim() != _LocationMasterTable.stbllocn.Trim())
                {
                    ScreenHandler.DefaultText = _Location;
                    Error("LOCATIONMISMATCH");
                }
                else
                {
                    _Location = EmptyStringCompatible(_LocationMasterTable.stbllocn);
                    ScreenHandler.ScreenMap.Add("Location", _LocationMasterTable.sscnlocn);
                    Next(_VerifyItemNumber);
                }
            }
            else
            {
                Error("LOCATION");
            }
        }

        #region VerifyLocation_KeyEvent

        private void VerifyLocation_KeyEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            switch (e.KeyPressed)
            {
                case ActionKey.F2: // user hits F2 - Capture Unexpected Inventory
                    if (WFOptions.GetYesNoWFOptionValue("UnexpectedInv"))
                    {
                        _AddCalledFrom = AddCalledFrom.Location;
                        _SavedCountType = _CountType;
                        UnlockCountRecord();
                        _AddedCountRecord = true;
                        _LocationBeforeF2 = _CycleCountDetailTable.PJLOCN.ToString();
                        _ThisCountType = _WorkflowOptionCountType.Random.ToString("D");
                        Next(_CollectLocation);
                    }
                    else
                    {
                        Error("NOTALLOWED");
                    }

                    break;

                case ActionKey.Enter:
                    ProcessVerifyLocationEnterKey(e);
                    break;
                default:
                    Error("JDEWrongKey");
                    break;
            }
        }

        #endregion

