        private void ProcessVerifyItemNumberEnterKey(ScreenEventArgs e)
        {
            _CollectItemNumber.ItemsTable.ResetAll();
            _ItemCrossReferenceTable.ResetAll();
            // use the returned result to display the proper item number
            if (e.UserInput.ToString().Trim().Length == 0)
            {
                Error("ITEMNUMBER");
                return;
            }

            _PrimaryItemNumber = _CollectItemNumber.ItemsTable.RetrieveItem(_CollectBranch.BranchPlantsTable.MCMCU.ToString(), e.UserInput.ToString().ToUpper(), _CollectBranch.WarehouseConstantsTable._DesignatedPrimaryItemNumber.ToString());
            // if the primary item number is null, then an invalid item was scanned
            if (_PrimaryItemNumber == null)
            {
                ScreenHandler.DefaultText = e.UserInput.ToString();
                Error("ITEMNUMBER");
                return;
            }

            ScreenHandler.ScreenMap.Add("ItemNumber", _PrimaryItemNumber);
            if (_CollectItemNumber.ItemsTable.IMITM != _CycleCountDetailTable.PJITM)
            {
                ScreenHandler.DefaultText = e.UserInput.ToString();
                Error("ITEMMISMATCH");
                return;
            }

            _CollectItemNumber.ItemBranchesTable.ResetAll();
            _CollectItemNumber.ItemBranchesTable.IBMCU = _Branch;
            _CollectItemNumber.ItemBranchesTable.IBITM = _CycleCountDetailTable.PJITM;
            if (!_CollectItemNumber.ItemBranchesTable.Fetch())
            {
                ScreenHandler.DefaultText = e.UserInput.ToString();
                Error("ITEMLOCATION");
                return;
            }

            if (_CollectItemNumber.ItemBranchesTable.IBSRCE.Trim().Length > 0)
                Next(_VerifyLotSerialNumber);
            else
            {
                Next(_CollectQuantity);
            }
        }

        #endregion

