        #region CycleCountList_EnterEvent

        private void CycleCountList_EnterEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            string sPrimaryItem = null;
            _CycleCountDetailTable.UpdateCurrentRow();
            _ShortItemNumber = _CycleCountDetailTable.PJITM; // short item number
            _LongItemNumber = _CycleCountDetailTable.PJLITM; // 2nd item number
            _ThirdItemNumber = _CycleCountDetailTable.PJAITM; // 3rd item number
            // load primary item in order to retrieve info
            switch (_CollectBranch.WarehouseConstantsTable._DesignatedPrimaryItemNumber)
            {
                case PrimaryItemNumberDesignations.ShortNumber:
                    sPrimaryItem = _ShortItemNumber.ToString();
                    break;
                case PrimaryItemNumberDesignations.LongNumber:
                    sPrimaryItem = _LongItemNumber;
                    break;
                case PrimaryItemNumberDesignations.ThirdNumber:
                    sPrimaryItem = _ThirdItemNumber;
                    break;
            }

            if (RetrieveMasterInfo(sPrimaryItem))
            {
                if (_CollectItemNumber.ItemsTable.IMITM != _CycleCountDetailTable.PJITM)
                {
                    ScreenHandler.DefaultText = e.UserInput.ToString();
                    Error("ITEMMISMATCH");
                }
                else
                {
                    if (_CollectItemNumber.ItemBranchesTable.IBSRCE.ToString().Trim().Length > 0)
                        Next(_VerifyLotSerialNumber);
                    else
                        Next(_CollectQuantity);
                }
            }
            else
            {
                ScreenHandler.DefaultText = e.UserInput.ToString();
                Error("ITEMNUMBER");
            }
        }

