        private void FromLocationEnter(string Locn)
        {
            _LocationMasterTable.ResetAll();
            _LocationMasterTable.MCU = _TableFormattedBranchPlant;
            _LocationMasterTable.inLOCN = Locn;
            if (_LocationMasterTable.ValidateLocation())
            {
                _ScreenFormattedFromLocation = _LocationMasterTable.sscnlocn;
                _TableFormattedFromLocation = _LocationMasterTable.stbllocn;
                _FromLocation = _LocationMasterTable.stbllocn;
                // Retrieve first record within location sequence
                _LastLocationProcessed = _TableFormattedFromLocation;
                ScreenHandler.ScreenMap.Add("FROMLOCATION", _ScreenFormattedFromLocation);
                Next(_CollectToLocation);
            }
            else
            {
                ScreenHandler.DefaultText = Locn;
                Error("LOCATION");
