        private void ToLocationEnter(string Locn)
        {
            // validate that the to location exists

            _LocationMasterTable.ResetAll();
            _LocationMasterTable.MCU = _TableFormattedBranchPlant;
            _LocationMasterTable.inLOCN = Locn;

            if (_LocationMasterTable.ValidateLocation())
            {
                if (_TableFormattedFromLocation.CompareTo(_LocationMasterTable.stbllocn) > 0) // the first value is greater than the second value
                {
                    Error("LocRangeError");
                    return;
                }

                _TableFormattedToLocation = _LocationMasterTable.stbllocn;

                _ScreenFormattedToLocation = _LocationMasterTable.sscnlocn;
                //if (_CountDetailTable.Rows.Count == 0)
                LoadDataSet("FromTo", _TableFormattedFromLocation, _TableFormattedToLocation);
                switch (RetrieveCycleCountRecord())
                {
                    case 0:
                        if (SaveFieldsForVerification())
                            Next(_VerifyLocation);
                        else
                        {
                            ScreenHandler.ScreenMap.Add("EndOfCount", ScreenHandler.RetrieveVocabularyOverride("ENDOFCOUNT"));
                            Back(_CollectCycleNumber);
                        }

                        break;
                    case 1:
                        ScreenHandler.ScreenMap.Add("EndOfCount", ScreenHandler.RetrieveVocabularyOverride("ENDOFCOUNT"));
                        Back(_CollectCycleNumber);
                        break;
                    case -1:
                        DisplayLockInformation();
                        break;
                    default:
                        ScreenHandler.ScreenMap.Add("EndOfCount", ScreenHandler.RetrieveVocabularyOverride("ENDOFCOUNT"));
                        Back(_CollectCycleNumber);
                        break;
                }
            }
            else
            {
                ScreenHandler.DefaultText = Locn;
                Error("LOCATION");
            }
        }

