        private void SkipToLocationEnter(string Locn)
        {
            _LocationMasterTable.ResetAll();
            _LocationMasterTable.MCU = _TableFormattedBranchPlant;
            _LocationMasterTable.inLOCN = Locn;
            if (_LocationMasterTable.ValidateLocation())
            {
                // for random counts, return to Collect Location
                if (_CountType == "4") // Random
                {
                    ScreenHandler.DefaultText = Locn;
                    Next(_CollectLocation);
                    return;
                }

                _ScreenFormattedFromLocation = _LocationMasterTable.sscnlocn;
                _TableFormattedFromLocation = _LocationMasterTable.stbllocn;

                if (!RangeChecksPassed())
                    return;

                // Retrieve first record within location sequence
                _LastLocationProcessed = _TableFormattedFromLocation;
                ScreenHandler.ScreenMap.Add("FROMLOCATION", _ScreenFormattedFromLocation);
                _Location = EmptyStringCompatible(_LocationMasterTable.stbllocn);
                _SkipTo = true;
                switch (RetrieveCycleCountRecord())
                {
                    case 0:
                        if (SaveFieldsForVerification())
                        {
                            for (int i = _NextRecord; i < _CountLocationsTable.Rows.Count; i++)
                            {
                                if ((_CountLocationsTable.Rows[i]["Location"].ToString().Trim() == _Location.Trim()))
                                {
                                    _NextRecord = i;
                                    break;
                                }
                            }

                            Next(_VerifyLocation);
                        }
                        else
                            Back(_CollectCycleNumber);

                        break;
                    case 1:
                        ScreenHandler.ScreenMap.Add("EndOfCount", ScreenHandler.RetrieveVocabularyOverride("ENDOFCOUNT"));
                        Back(_CollectCycleNumber);
                        break;
                    case -1:
                        DisplayLockInformation();
                        break;
                    default:
                        Back(_CollectCycleNumber);
                        break;
                }
            }
            else
            {
                ScreenHandler.DefaultText = Locn;
                Error("LOCATION");
            }
        }

