        #region RangeChecksPassed

        private bool RangeChecksPassed()
        {
            // if a from/to location range has been entered, we need to verify that the skip to has not 
            // exceeded this range
            if ((_FromLocation != null) && (_FromLocation.Trim().Length > 0))
            {
                if (String.Compare(_TableFormattedFromLocation, _FromLocation) < 0)
                {
                    Error("OutOfRange", _ScreenFormattedFromLocation);
                    return false;
                }

                if (String.Compare(_TableFormattedFromLocation, this._TableFormattedToLocation) > 0)
                {
                    Error("OutOfRange", _ScreenFormattedFromLocation);
                    return false;
                }
            }

            // if a prefix was entered, we need to perform the same check
            if ((_LocationPrefix != null) && (_LocationPrefix.Trim().Length > 0))
            {
                if (String.Compare(_TableFormattedFromLocation.Substring(0, _LocationPrefix.Length), _LocationPrefix) != 0)
                {
                    Error("OutOfRange", _ScreenFormattedFromLocation);
                    return false;
                }
            }

            return true;
        }

