        /// <returns></returns>
        string EmptyStringCompatible(string emptyString)
        {
            return (emptyString == "") ? " " : emptyString;
        }

        #region CollectLocation_EnterEvent

        /// <summary>
        /// Some Comments
        /// </summary>
        private void CollectLocation_EnterEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            // validate the location
            _Location = EmptyStringCompatible(e.UserInput.ToString().ToUpper());

            _LocationMasterTable.ResetAll();
            _LocationMasterTable.MCU = _TableFormattedBranchPlant;
            _LocationMasterTable.inLOCN = _Location;
            if (_LocationMasterTable.ValidateLocation())
            {
                _Location = EmptyStringCompatible(_LocationMasterTable.stbllocn);
                ScreenHandler.ScreenMap.Add("Location", _LocationMasterTable.sscnlocn);
                //CC035890 - Changed it to Load the dataset after collecting location
                if (_CountLocationsTable.Rows.Count == 0)
                {
                    LoadDataSet("Random", "", "");
                }

                if (_CountType == "6")
                {
                    if (_PITagTable.PILOCN != "")
                    {
                        if (_PITagTable.PILOCN.Trim() != _Location)
                        {
                            throw new RFS_Exception("LOCATIONMISMATCH");
                        }
                    }
                    else
                    {
                        if (_Location.Trim() == "")
                        {
                            throw new RFS_Exception("BLANKSNOTALLOWED");
                        }
                    }
                }

                Next(_CollectItemNumber);
            }
            else
            {
                ScreenHandler.DefaultText = e.UserInput.ToString();
                Error("LOCATION");
            }
        }

