        #region CollectItemNumber_EnterEvent

        /// <summary>
        /// Some Comments
        /// </summary>
        private void CollectItemNumber_EnterEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            if (e.UserInput.ToString().Trim().Length > 0)
            {
                // set up parameters for item number verification
                ItemNumberEnter(e.UserInput.ToString());
            }
            else
                Error("ITEMNUMBER");
        }

        private void ItemNumberEnter(string sitem)
        {
            if (_CountType == "6")
            {
                if (_CustomCycleCountDetailTable.GetCycleCount(_Branch, sitem, _Location))
                {
                    _CycleCountNumber = _CustomCycleCountDetailTable.PJCYNO.ToString();
                    Log.Debug($"<***> Cycle Count Number = {_CycleCountNumber}");
                    CycleCountExists();
                }
                else
                {
                    if (_CustomCycleCountDetailTable.GetDefaultCycleCount(_Branch))
                    {
                        _CycleCountNumber = _CustomCycleCountDetailTable.PJCYNO.ToString();
                        Log.Debug($"<***> Default Cycle Count Number = {_CycleCountNumber}");
                        CycleCountExists();
                    }
                }

                Log.Debug($"<***> _PITagTable.PILITM.Trim() {_PITagTable.PILITM.Trim()} _PrimaryItemNumber {sitem}");
                if (_PITagTable.PILITM.Trim() != sitem)
                {
                    throw new RFS_Exception("ITEMMISMATCH");
                }
            }

            if (RetrieveMasterInfo(sitem.ToUpper()))
            {
                ScreenMap.Add("DocUOMValue", _CollectItemNumber.ItemsTable.DefaultUOM(WFOptions.RetrieveOptionValue("DefaultUOM").ToString()));
                if (_CollectItemNumber.ItemBranchesTable.ValidateItemBranch(_TableFormattedBranchPlant, _CollectItemNumber.ItemsTable.IMITM))
                    _LotProcessType = _CollectItemNumber.ItemBranchesTable.IBSRCE;
                else
                    _LotProcessType = _CollectItemNumber.ItemsTable.IMSRCE;

                // validate item/location here
                _ItemLocationTable.ValidateItemLocationRecord(_TableFormattedBranchPlant, _CollectItemNumber.ItemsTable.IMITM, _Location);

                ScreenHandler.ScreenMap.Clear("sscnlocn");
                // if this is not a lot controlled item, retrieve the count detail record
                // check to see if this is a lot controlled item, and if so, display the lot
                // verification screen
                // for serialized items, at this point we need to capture each S/N
                if ((_LotProcessType.Length > 0) && (_CountType != "5" && _CountType != "6"))
                {
                    Next(_CollectLotNumber);
                    return;
                }

                _LotNumber = "";

                if (!CycleCountRetrieved())
                {
                    if (WFOptions.GetYesNoWFOptionValue("UnexpectedInv"))
                    {
                        /*if (_CustomCycleCountDetailTable.GetCycleCount(_Branch, _LongItemNumber, _Location))
                        {
                            //Save the current Cycle Count Number
                            _PreviousCycleCountNumber = _CycleCountNumber;
                            _CycleCountNumber = _CustomCycleCountDetailTable.PJCYNO.ToString();
                            CycleCountExists();
                            Next(_CollectQuantity);
                            return;
                        }
                        else
                        {*/
                        Next(_AddRandomCount);
                        return;
                        //}
                    }
                    else
                    {
                        Error("NOTALLOWED");
                        return;
                    }
                }
                else
                {
                    if (_CycleCountDetailTable.IsLocked(_ERPRecordLockTable, ScreenHandler.Environment.ToString()))
                    {
                        DisplayLockInformation();
                        return;
                    }

                    if (!WFOptions.GetYesNoWFOptionValue("AllowRecount"))
                    {
                        if (_CycleCountDetailTable.PJCCCD == "1")
                        {
                            Error("RECOUNTNOTALLOWED");
                            return;
                        }
                    }

                    // lock the count record
                    _CycleCountDetailTable.LockRecord(_ERPRecordLockTable, ScreenHandler.Environment.ToString(), UserSession.CurrentUser.LoginName.ToString(), ScreenHandler.WorkflowID.ToString());
                    if ((_LotProcessType.Trim().Length > 0) &&
                        (Convert.ToInt16(_LotProcessType) > Convert.ToInt16(LotSerialDesignations.LotRequired)))
                    {
                        ScreenHandler.DefaultText = "1";
                        Next(_CollectQuantity);
                    }
                    else
                        Next(_CollectQuantity);
                }
            }
            else
            {
                ScreenHandler.DefaultText = sitem;
                Error("ITEMNUMBER");
            }
        }

