        #region CollectLotNumber_EnterEvent

        /// <summary>
        /// Some Comments
        /// </summary>
        private void CollectLotNumber_EnterEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            switch (WFOptions.RetrieveOptionValue("CountType"))
            {
                case "5":
                    if (e.UserInput.ToString().Trim().Length > 0)
                    {
                        if (double.TryParse(e.UserInput.ToString(), out _TagNumber))
                        {
                            if (_PITagTable.GetTagNumber(_Branch, _TagNumber, true))
                            {
                                if (_PITagTable.GetTagNumber(_Branch, _TagNumber))
                                {
                                    Next(_CollectLocation);
                                }
                                else
                                {
                                    throw new RFS_Exception("ALREADYSCANNED");
                                }
                            }
                            else
                            {
                                throw new RFS_Exception("TAGNOTFOUND");
                            }
                        }
                        else
                        {
                            throw new RFS_Exception("INVALIDINPUT");
                        }
                        // set up parameters for serial number verification
                        //ItemNumberEnter(e.UserInput.ToString());
                    }
                    else
                    {
                        throw new RFS_Exception("BLANKSNOTALLOWED");
                    }

                    break;
                //}
                //if (WFOptions.RetrieveOptionValue("CountType") == "5" || WFOptions.RetrieveOptionValue("CountType") == "6")
                //{

                //}
                //else
                //Collecting regular label serial numbers
                //{

                //if (WFOptions.RetrieveOptionValue("CountType") == "6")
                //{
                case "6":
                    if (e.UserInput.ToString().Trim().Length > 0)
                    {
                        if (double.TryParse(e.UserInput.ToString(), out _TagNumber))
                        {
                            if (_PITagTable.GetTagNumber(_Branch, _TagNumber, true))
                            {
                                if (_PITagTable.GetTagNumber(_Branch, _TagNumber))
                                {
                                    Next(_CollectLocation);
                                }
                                else
                                {
                                    throw new RFS_Exception("ALREADYSCANNED");
                                }
                            }
                            else
                            {
                                if (_SerialTagTable.GetSerialNumber(_Branch, e.UserInput.ToString(), false))
                                {
                                    Log.Debug($"<***> Get Carton Number");
                                    if (_PITagTable.GetTagNumber(_Branch, e.UserInput.ToString(), true))
                                    {
                                        if (_PITagTable.GetTagNumber(_Branch, e.UserInput.ToString()))
                                        {
                                            Log.Debug($"<***> Check for Master Carton");
                                            if (_PITagTable.PIGNUM2 == 0)
                                            {
                                                _TagNumber = _PITagTable.PITGG;
                                                Next(_CollectLocation);
                                            }
                                            else
                                            {
                                                throw new RFS_Exception("ONAMASTERTAG");
                                                //_TagNumber = _PITagTable.PIGNUM2;
                                                //_PITagTable.GetTagNumber(_Branch, _TagNumber);
                                                //Next(_CollectLocation);
                                            }
                                        }
                                        else
                                        {
                                            throw new RFS_Exception("ALREADYSCANNED");
                                        }
                                    }
                                    else
                                    {
                                        int NextNumber;
                                        string NextSerialNumber;
                                        _NextNumberTable.GetNextNumber("InventoryTag", out NextNumber, out NextSerialNumber);
                                        Log.Debug($"<***> NextSerialNumber {NextSerialNumber}");
                                        _TagNumber = NextNumber;
                                        _PITagTable.InsertPITag(_Branch, _SerialTagTable.LPITM.ToString(), _SerialTagTable.LPLITM, "",
                                            _SerialTagTable.LPTQTY.ToString(), _TagNumber.ToString(), UserSession.UserId, _SerialTagTable.LPLPNU, "SrlTag");
                                        if (_PITagTable.GetTagNumber(_Branch, _TagNumber))
                                        {
                                            Next(_CollectLocation);
                                        }
                                        else
                                        {
                                            throw new RFS_Exception("TAGNOTFOUND");
                                        }
                                    }
                                }
                                else
                                {
                                    throw new RFS_Exception("TAGNOTFOUND");
                                }
                            }
                        }
                        else
                        {
                            throw new RFS_Exception("TAGNOTFOUND");
                        }
                    }
                    else
                    {
                        throw new RFS_Exception("INVALIDINPUT");
                    }

                    break;
                //}
                case "7":
                    if (e.UserInput.ToString().Trim().Length > 0)
                    {
                        if (double.TryParse(e.UserInput.ToString(), out _TagNumber))
                        {
                            if (_PITagTable.GetTagNumber(_Branch, _TagNumber, true))
                            {
                                if (_PITagTable.PIJOBN == "")
                                {
                                    throw new RFS_Exception("NOTSCANNED");
                                }

                                if (_PITagTable.PIDL03 == "")
                                {
                                    _PITagTable.UpdateAuditScan(_Branch, _TagNumber, UserSession.CurrentUser.LoginName);
                                }

                                Next(_DisplayAudit);
                            }
                            else
                            {
                                if (_PITagTable.GetTagNumber(_Branch, e.UserInput.ToString(), true))
                                {
                                    //if (_PITagTable.GetTagNumber(_Branch, e.UserInput.ToString()))
                                    //{
                                    _TagNumber = _PITagTable.PITGG;
                                    if (_PITagTable.PIJOBN == "")
                                    {
                                        throw new RFS_Exception("NOTSCANNED");
                                    }

                                    if (_PITagTable.PIDL03 == "")
                                    {
                                        _PITagTable.UpdateAuditScan(_Branch, _TagNumber, UserSession.CurrentUser.LoginName);
                                    }

                                    Next(_DisplayAudit);
                                }
                                else
                                {
                                    throw new RFS_Exception("NOTSCANNED");
                                }
                            }
                        }
                        //}
                    }

                    break;
                //else
                //{
                default:
                    // TODO - if the lot/location does not exist, warn showing lot/serial warning
                    _LotNumber = (string) e.UserInput;
                    ScreenHandler.ScreenMap.Add("LotNumber", _LotNumber);
                    if (_LotProcessType.Trim().Length > 0)
                    {
                        if (!CycleCountRetrieved())
                        {
                            if (WFOptions.GetYesNoWFOptionValue("UnexpectedInv"))
                            {
                                Next(_AddRandomCount);
                                return;
                            }
                            else
                            {
                                Error("NOTALLOWED");
                                return;
                            }
                        }

                        if (_CycleCountDetailTable.IsLocked(_ERPRecordLockTable, ScreenHandler.Environment.ToString()))
                        {
                            DisplayLockInformation();
                            return;
                        }

                        if (!WFOptions.GetYesNoWFOptionValue("AllowRecount"))
                        {
                            if (_CycleCountDetailTable.PJCCCD == "1")
                            {
                                Error("RECOUNTNOTALLOWED");
                                return;
                            }
                        }

                        // lock the count record
                        _CycleCountDetailTable.LockRecord(_ERPRecordLockTable, ScreenHandler.Environment.ToString(), UserSession.CurrentUser.LoginName.ToString(), ScreenHandler.WorkflowID.ToString());

                        if (Convert.ToInt16(_LotProcessType) > Convert.ToInt16(LotSerialDesignations.LotRequired))
                        {
                            ScreenHandler.DefaultText = "1";
                            /* _TransactionQuantity = 1;
                            _UnitOfMeasure = _ItemMasterTable.IMUOM1;
                            ScreenHandler.ScreenMap.Add("QUANTITY", _TransactionQuantity.ToString());
                            ScreenHandler.ScreenMap.Add("UnitOfMeasure", _UnitOfMeasure.ToString());
                            ProcessUOMEnter(); */
                            Next(_CollectQuantity);
                        }
                        else
                            Next(_CollectQuantity);
                    }
                    else
                        Next(_CollectQuantity);

                    break;
            }
        }

