        #region CollectQuantity_EnterEvent

        private double ConvertToUOMQty(string fromUOM, string toUOM, double qty)
        {
            double factor = 0;
            if (fromUOM == toUOM)
            {
                factor = 1;
            }
            else
            {
                factor = this._UnitOfMeasureConversionTable1.ConvertToPrimaryUOM(_CollectBranch.BranchPlant,
                    _CollectItemNumber.ShortItemNumber,
                    fromUOM,
                    toUOM);
                if (factor == 0)
                    factor = _UnitOfMeasureConversionTable2.ConvertToPrimaryUOM(fromUOM, toUOM);
            }

            return (factor * qty);
        }

        /// <summary>
        /// Some Comments
        /// </summary>
        private void CollectQuantity_EnterEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            // Call calculator function
            try
            {
                string CalculatedQuantity = _ItemLocationTable.CalcQty(e.UserInput.ToString().ToUpper());

                if (CalculatedQuantity == null)
                {
                    ScreenHandler.DefaultText = e.UserInput.ToString();
                    Error("INVALIDQUANTITY");
                    return;
                }

                if (Convert.ToDecimal(CalculatedQuantity) < 0)
                {
                    ScreenHandler.DefaultText = e.UserInput.ToString();
                    Error("NEGATIVEENTRY");
                    return;
                }
                else
                {
                    // for serialized items, at this point we need to capture each S/N
                    if ((_CollectItemNumber.ItemBranchesTable.IBSRCE.Trim().Length > 0)
                        && (Convert.ToInt16(_CollectItemNumber.ItemBranchesTable.IBSRCE.ToString()) > Convert.ToInt16(LotSerialDesignations.SerialOptional))
                        && (Convert.ToDecimal(CalculatedQuantity) > 1))
                    {
                        Error("SNQUANTITY", e.UserInput.ToString());
                        return;
                    }

                    _TransactionQuantity = Convert.ToDouble(CalculatedQuantity);
                    _EnteredQty = Convert.ToDouble(CalculatedQuantity);
                    ScreenHandler.ScreenMap.Add("QUANTITY", _TransactionQuantity.ToString());

                    if (_CountType == "6")
                    {
                        Log.Debug($"<***>_PITagTable.PITRQT {_PITagTable.PITRQT} _TransactionQuantity {_TransactionQuantity}");
                        if (_PITagTable.PITRQT != _TransactionQuantity)
                        {
                            Log.Debug($"<***>{_PITagTable.PITRQT != _TransactionQuantity}");
                            Error("INVALIDQUANTITY");
                            return;
                        }
                    }

                    if (_TransactionQuantity == 0)
                    {
                        _TransactionQuantity = 0;
                        _UnitOfMeasure = _CollectItemNumber.ItemsTable.IMUOM1.ToString();
                        ProcessUOMEnter();
                        return;
                    }

                    ScreenHandler.DefaultText = _CollectItemNumber.ItemsTable.DefaultUOM(WFOptions.RetrieveOptionValue("DefaultUOM").ToString());
                    Next(_CollectUnitOfMeasure);

                    _CollectQuantity.Validate(_TransactionQuantity.ToString());
                }
            }
            catch
            {
                Error("INVALIDQUANTITY");
            }
        }

        #endregion

        #region CollectQuantity_BackEvent

        /// <summary>
        /// Some Comments
        /// </summary>
        private void CollectQuantity_BackEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            switch (_AddCalledFrom)
            {
                case AddCalledFrom.Location: // from location
                    _AddCalledFrom = AddCalledFrom.None;
                    UnlockCountRecord();
                    RetrieveCycleCountRecord();
                    SaveFieldsForVerification();
                    RestartLoop(_VerifyLocation);
                    break;
                case AddCalledFrom.Item:
                    _AddCalledFrom = AddCalledFrom.None;
                    UnlockCountRecord();
                    RetrieveCycleCountRecord();
                    SaveFieldsForVerification();
                    Back(_VerifyItemNumber);
                    break;
                default:
                    switch (_CountType)
                    {
                        case "1": // Directed Count
                        case "2":
                        case "3":
                            if ((_CollectItemNumber.ItemBranchesTable.IBSRCE.Trim().Length > 0))
                                Back(_VerifyLotSerialNumber);
                            else
                                Back(_VerifyItemNumber);
                            break;
                        case "4": // Random Count
                            UnlockCountRecord();
                            Back(_CollectItemNumber);
                            break;
                    }

                    break;
            }
        }

