        private void ProcessUOMEnter()
        {
            // validate U/M
            double _ConversionFactor = 0;
            double WorkQuantity = 0;

            // validate unit of measure
            if (_UnitOfMeasure != _CollectItemNumber.ItemsTable.IMUOM1)
            {
                #region Log Process UOM Enter

                Log.Debug("Tracking CycleCount: ProcessUOMEnter: Conversion Factor after call to ConvertToPrimaryUOM = " + _ConversionFactor.ToString());
                Log.Debug("Tracking CycleCount: ProcessUOMEnter: Branch/Plant = " + _TableFormattedBranchPlant);
                Log.Debug("Tracking CycleCount: ProcessUOMEnter: Short Item Number = " + _ShortItemNumber.ToString());
                Log.Debug("Tracking CycleCount: ProcessUOMEnter: From U/M = " + _UnitOfMeasure.ToString());
                Log.Debug("Tracking CycleCount: ProcessUOMEnter: To U/M = " + _CollectItemNumber.ItemsTable.IMUOM1.ToString());

                #endregion

                if (_ConversionFactor == 0)
                {
                    _ConversionFactor = _UnitOfMeasureConversionTable2.ConvertToPrimaryUOM(_UnitOfMeasure, _CollectItemNumber.ItemsTable.IMUOM1.ToString());
                }
            }
            else
            {
                _ConversionFactor = 1;
            }

            Log.Debug($"<***> IncrementCountQuantity");
            if (WFOptions.GetYesNoWFOptionValue("IncrementCountQuantity") && _CycleCountDetailTable.PJTQCT != 0)
            {
                _TransactionQuantity = _TransactionQuantity + ConvertToUOMQty(_CollectItemNumber.ItemsTable.IMUOM1, _UnitOfMeasure, _CycleCountDetailTable.PJTQCT);
            }

            #region Log Process UOM Enter

            Log.Debug("Tracking CycleCount: ProcessUOMEnter: Conversion Factor = " + _ConversionFactor.ToString());

            #endregion

            if (_ConversionFactor != 0)
            {
                #region Log Process UOM Enter

                Log.Debug("Tracking CycleCount: ProcessUOMEnter: Transaction Quantity before applying conversion factor = " + _TransactionQuantity.ToString());

                #endregion

                WorkQuantity = _TransactionQuantity * _ConversionFactor;

                #region Log Process UOM Enter

                Log.Debug("Tracking CycleCount: ProcessUOMEnter: Transaction Quantity after applying conversion factor = " + WorkQuantity.ToString());

                #endregion

                _TransactionQuantity = WorkQuantity;

                if (ToleranceCheckPassed())
                {
                    double LooseQuantity = CalculateLooseQuantity();
                    ScreenHandler.ScreenMap.Add("PREVIOUSQTY", LooseQuantity.ToString());
                    ScreenHandler.ScreenMap.Add("UnitOfMeasure", _UnitOfMeasure);
                    ScreenHandler.ScreenMap.Add("CountDetailUOM", _CollectItemNumber.ItemsTable.IMUOM1.ToString());
                    if (_CycleCountDetailTable.PJCCCD.ToString().Trim() == "1")
                    {
                        Log.Debug($"<***> _VerifyRecount");
                        Next(_VerifyRecount);
                    }
                    else
                    {
                        Process();
                    }
                }
                else
                    Next(_DisplayToleranceWarning);

                _CollectUnitOfMeasure.Validate(_UnitOfMeasure);
            }
            else
            {
                ScreenHandler.DefaultText = _UnitOfMeasure;
                Error("UNITOFMEASURE");
            }
        }

        private void Process()
        {
            Log.Debug($"<***> _CollectDualQuantity");
            //Next(_CollectDualQuantity);
            //skip _CollectDualQuantity screen
            //_CollectDualQuantity.CancelLoad = true;
            //_CollectDualUnitOfMeasure.CancelLoad = true;
            //_DualQuantity = _CollectDualQuantity.Quantity;

            #region CollectDualUnitofMeasure

            //Log.Debug($"<***> Collect Dual Unit of Measure");
            //_DualUnitOfMeasure = _CollectDualUnitOfMeasure.UnitOfMeasure;

            SendToERP();
            ClearTransaction();
            UnlockCountRecord();

            if (_CountType == _WorkflowOptionCountType.Random.ToString("D"))
                RestartLoop(_CollectLocation);
            else
            {
                if (_CountType == _WorkflowOptionCountType.PI.ToString("D") || _CountType == _WorkflowOptionCountType.PILEX.ToString("D"))
                {
                    RestartLoop(_CollectLotNumber);
                }
                else
                {
                    _SkipTo = false;
                    switch (RetrieveCycleCountRecord())
                    {
                        case 0:
                            if (SaveFieldsForVerification())
                                RestartLoop(_VerifyLocation);
                            else
                                RestartLoop(_CollectCycleNumber);
                            break;
                        case 1:
                            ScreenHandler.ScreenMap.Add("EndOfCount", ScreenHandler.RetrieveVocabularyOverride("ENDOFCOUNT"));
                            RestartLoop(_CollectCycleNumber);
                            break;
                        case -1:
                            DisplayLockInformation();
                            break;
                        default:
                            RestartLoop(_CollectCycleNumber);
                            break;
                    }
                }
            }

            #endregion
        }

