        #region ToleranceCheckPassed

        private bool ToleranceCheckPassed()
        {
            bool _ReturnValue = true;
            _ItemLocationTable.ResetAll();
            if (!_ItemLocationTable.RetrieveSpecificRecord(_Branch, _ShortItemNumber, _Location, _LotNumber))
                _ItemLocationTable.LIPQOH = 0;
            if (_CycleCountDetailTable.PJTQOH != 0)
            {
                #region Log Tolerance Check Passed

                Log.Debug("Tracking CycleCount: ToleranceCheckPassed: Tolerance Checking = ");

                #endregion

                double _WorkingQuantity = 0;
                if (!_FromLicensePlate)
                {
                    #region Log Tolerance Check Passed

                    Log.Debug("Tracking CycleCount: ToleranceCheckPassed: PJTQOH = " + _CycleCountDetailTable.PJTQOH.ToString());
                    Log.Debug("Tracking CycleCount: ToleranceCheckPassed: LIPQOH = " + _ItemLocationTable.LIPQOH.ToString());

                    #endregion

                    if (WFOptions.GetYesNoWFOptionValue("UpdateCountOnHandQuantity"))
                        _WorkingQuantity = (_TransactionQuantity / _ItemLocationTable.LIPQOH) * 100;
                    else
                        _WorkingQuantity = (_TransactionQuantity / _CycleCountDetailTable.PJTQOH) * 100;
                }

                #region Log Tolerance Check Passed

                Log.Debug("Tracking CycleCount: ToleranceCheckPassed: TransactionQuantity/PJTQOH or LIPQOH = " + _WorkingQuantity.ToString());
                Log.Debug("Tracking CycleCount: ToleranceCheckPassed: WFO Tolerance percent = " + _WFOTolerancePercent.ToString());

                #endregion

                if (_WorkingQuantity < 0)
                {
                    _WorkingQuantity = _WorkingQuantity * -1;
                } // reverse sign

                double zwrk = 100 - _WorkingQuantity;
                if (zwrk < 0)
                    zwrk *= -1;
                if (zwrk > _WFOTolerancePercent)
                {
                    _ReturnValue = false;
                }
            }
            else // zero on hand
            {
                if (_TransactionQuantity > 0) // if counted, issue tolerance warning
                {
                    _ReturnValue = false;
                }
            }

            return _ReturnValue;
        }

