        #region RetrieveCycleCountRecord

        private int RetrieveCycleCountRecord()
        {
            int ReturnValue = 0;
            // Loop until we return a value;
            while (true)
            {
                //_CountDetailTable is a list of locations for the count. 
                //_CycleCountDetailTable is all the counts for a location. Lets step through this recordset to get each row. 
                if (_NextRecord == -1 || !_CycleCountDetailTable.MoveNext())
                {
                    // If _NextRecord = -1 we have not counted anything at the location yet and we need to get ALL the counts for the location.
                    // If _CycleCountDetailTable.MoveNext = false all rows for the location have been counted and we need to move to the next location.

                    //If we added unexpected inventory and we are doing a type of directed count. (Not a random count)
                    if (_AddedCountRecord && _CountType != "4")
                    {
                        //If we added unexpected inventory to our directed count, return to the same count record we were on. 
                        _AddedCountRecord = false;
                    }
                    else
                    {
                        //Go to the next count record
                        _NextRecord++;
                    }

                    #region Log Retrieve Cycle Count Record

                    Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: _NextRecord = " + _NextRecord);

                    #endregion

                    if (_NextRecord >= _CountLocationsTable.Rows.Count)
                    {
                        #region Log Retrieve Cycle Count Record

                        Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: No records left. _NextRecord = " + _NextRecord +
                                  "_CycleCountDetailTable.Rows.Count = " + _CountLocationsTable.Rows.Count);
                        Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: Return Value from RetrieveCycleCountRecord() = -2");

                        #endregion

                        return -2; // no records left or found matching prefix.
                    }

                    string ThisLocation = _CountLocationsTable.Rows[_NextRecord]["Location"].ToString().Trim();

                    #region Log Retrieve Cycle Count Record

                    Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: ThisLocation = " + ThisLocation);

                    #endregion

                    // Now retrieve the Enterprise 1 cycle count detail record
                    if (
                        !_CycleCountDetailTable.RetrieveCountRecordsForLocation(
                            double.Parse(_CycleCountNumber),
                            _CollectBranch.BranchPlantsTable.MCMCU,
                            _SkipTo ? _Location : _CountLocationsTable.Rows[_NextRecord]["Location"].ToString(),
                            WFOptions.GetYesNoWFOptionValue("AllowRecount")))
                    {
                        #region Log Retrieve Cycle Count Record

                        Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: Unable to RetrieveCountRecordsForLocation: CycleCountNumber = " + _CycleCountNumber +
                                  " Branch = " + _CollectBranch.BranchPlantsTable.MCMCU + " Location = " + (_SkipTo ? _Location : _CountLocationsTable.Rows[_NextRecord]["Location"].ToString()));

                        #endregion

                        //No row for this location move to the Next Location
                        continue;
                    }
                }

                F4141 TempCount = new F4141(UserSession.DataAccess, "Temp");
                if (_CycleCountDetailTable.IsLocked(_ERPRecordLockTable, ScreenHandler.Environment.ToString()))
                {
                    #region Log Retrieve Cycle Count Record

                    Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: Row is Locked, moving onto the next one.");

                    #endregion

                    // If a row is locked move to the next one.
                    continue;
                }
                else if (!WFOptions.GetYesNoWFOptionValue("AllowRecount")
                         && TempCount.IsCounted(
                             _CycleCountDetailTable.PJCYNO,
                             _CycleCountDetailTable.PJITM,
                             _CycleCountDetailTable.PJMCU,
                             _CycleCountDetailTable.PJLOCN,
                             _CycleCountDetailTable.PJSTUN,
                             _CycleCountDetailTable.PJLOTN))
                {
                    #region Log Retrieve Cycle Count Record

                    Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: Row is Already Counted & Allow Recount is False: PJCYNO = " + _CycleCountDetailTable.PJCYNO +
                              " PJITM = " + _CycleCountDetailTable.PJITM + " PJMCU = " + _CycleCountDetailTable.PJMCU + " PJLOCN = " + _CycleCountDetailTable.PJLOCN + " PJSTUN = " + _CycleCountDetailTable.PJSTUN + " PJLOTN = " + _CycleCountDetailTable.PJLOTN);

                    #endregion

                    // This row is already counted and Allow Recount is false.
                    continue;
                }
                else
                {
                    if (_CycleCountDetailTable.LockRecord(
                            _ERPRecordLockTable,
                            ScreenHandler.Environment.ToString(),
                            UserSession.CurrentUser.LoginName.ToString(),
                            ScreenHandler.WorkflowID.ToString()))
                    {
                        ReturnValue = 0;
                    }
                    else
                    {
                        ReturnValue = 1;
                    }
                }

                #region Log Retrieve Cycle Count Record

                Log.Debug("Tracking CycleCount: RetrieveCycleCountRecord: Return Value from RetrieveCycleCountRecord() = " + ReturnValue);

                #endregion

                return ReturnValue;
            }
        }

        private int LoadDataSet()
        {
            switch (_CountType)
            {
                // If the workflow location filter is set to '1', grab and lock the first available record,
                // and the verify location screen is displayed
                case "1":
                    LoadDataSet("All", " ", " ");
                    break;
                // If the workflow location filter is set to '2', the collect from location range screen is next
                case "2":
                    LoadDataSet("FromTo", _TableFormattedFromLocation, _TableFormattedToLocation);
                    break;
                // If the workflow location filter is set to '3', the collect prefix start is next
                case "3":
                    LoadDataSet("Prefix", _LocationPrefix, " ");
                    break;
                case "4": // Random
                    Error("Location");
                    Next(_CollectLocation);
                    return 4;
                default:
                    Error("CountTypeWFO");
                    break;
            } // end switch

            return RetrieveCycleCountRecord();
        }

        #endregion

        #region SaveFieldsForVerification

        private bool SaveFieldsForVerification()
        {
            // retrieve the item master and item balance records
            switch (_CollectBranch.WarehouseConstantsTable._DesignatedPrimaryItemNumber)
            {
                case PrimaryItemNumberDesignations.ShortNumber:
                    RetrieveMasterInfo(_CycleCountDetailTable.PJITM.ToString());
                    break;
                case PrimaryItemNumberDesignations.LongNumber:
                    RetrieveMasterInfo(_CycleCountDetailTable.PJLITM);
                    break;
                case PrimaryItemNumberDesignations.ThirdNumber:
                    RetrieveMasterInfo(_CycleCountDetailTable.PJAITM);
                    break;
            }

            ScreenHandler.ScreenMap.Add("DocUOMValue", _CollectItemNumber.ItemsTable.DefaultUOM(WFOptions.RetrieveOptionValue("DefaultUOM").ToString()));
            _LocationMasterTable.ResetAll();
            _LocationMasterTable.MCU = _TableFormattedBranchPlant;
            _LocationMasterTable.inLOCN = _CycleCountDetailTable.PJLOCN.ToString();
            if (_LocationMasterTable.ValidateLocation())
            {
                ScreenHandler.ScreenMap.Add("VerifyLocation", _LocationMasterTable.sscnlocn);
                ScreenHandler.ScreenMap.Add("Location", _LocationMasterTable.sscnlocn);
            }
            else
            {
                ScreenHandler.ScreenMap.Add("VerifyLocation", _CycleCountDetailTable.PJLOCN.ToString());
                ScreenHandler.ScreenMap.Add("Location", _CycleCountDetailTable.PJLOCN.ToString());
            }

            ScreenHandler.ScreenMap.Add("Description", _CollectItemNumber.ItemsTable.IMDSC1);
            ScreenHandler.ScreenMap.Add("UnitOfMeasure", _CollectItemNumber.ItemsTable.IMUOM1);

            return true;
        }

        #endregion

        #region ShowNextScreen

        private bool ShowNextScreen()
        {
            bool ReturnValue = true;

            /*I am adding the CycleHeader_Number and CycleHeader_Desc1 to the screenmap here
             *because the ResetAll() and CountExistsInDifferentBranch leave the CycleHeaderTable
             *empty. This prevents the user from seeing the cycle number and description on the
             *VerifyLocation screen. Reference CS2614 & CS4192*/
            ScreenHandler.ScreenMap.Add("CycleNum", _CycleHeaderTable.PICYNO + "");
            ScreenHandler.ScreenMap.Add("CycleDesc1", _CycleHeaderTable.PIDSC1.Trim());

            if (_CycleHeaderTable.CountExistsInDifferentBranch(_CycleCountNumber, _TableFormattedBranchPlant, _StatusCodesAllowed))
            {
                Error("ExistsInDifferentBP");
            }

            _CycleHeaderTable.ShowBranchCycleCounts(_CycleCountNumber, _TableFormattedBranchPlant, _StatusCodesAllowed);
            // If the workflow option is set for a random count, display the collect location screen next
            ScreenHandler.ScreenMap.Clear("EndOfCount");

            switch (_CountType)
            {
                // If the workflow location filter is set to '1', grab and lock the first available record,
                // and the verify location screen is displayed
                case "1":
                    if (_CountLocationsTable.Rows.Count == 0)
                    {
                        LoadDataSet("All", " ", " ");
                    } // end if

                    switch (RetrieveCycleCountRecord())
                    {
                        case 0:
                            if (SaveFieldsForVerification())
                            {
                                Next(_VerifyLocation);
                            } // end if
                            else
                            {
                                ReturnValue = false;
                            } // end else

                            break;
                        case 1:
                            ReturnValue = false;
                            break;
                        case -1:
                            DisplayLockInformation();
                            break;
                        default:
                            ReturnValue = false;
                            break;
                    } // end switch

                    break;
                // If the workflow location filter is set to '2', the collect from location range screen is next
                case "2":
                    Next(_CollectFromLocation);
                    break;
                // If the workflow location filter is set to '3', the collect prefix start is next
                case "3":
                    Next(_CollectPrefix);
                    break;
                case "4": // Random
                    /*CC035890 - Changed it to Load the Data Set after collecting location
                    if (_CountDetailTable.Rows.Count == 0)
                    {
                       LoadDataSet("All", " ", " ");
                    } // end if
                    */
                    Next(_CollectLocation);
                    break;
                case "5": // Physical Inventory
                    Next(_CollectLotNumber);
                    break;
                case "6": // Physical Inventory
                    Next(_CollectLotNumber);
                    break;
                default:
                    ReturnValue = false;
                    Error("CountTypeWFO");
                    break;
            } // end switch

            return ReturnValue;
        } // end ShowNextScreen

        #endregion

        #region RetrieveMasterInfo

        private bool RetrieveMasterInfo(string sItm)
        {
            bool bRetVal = false;
            string sItemNumber = null;

            // Retrieve Item Master
            sItemNumber = _CollectItemNumber.ItemsTable.RetrieveItem(_Branch,
                sItm,
                _CollectBranch.WarehouseConstantsTable._DesignatedPrimaryItemNumber.ToString());
            if (sItemNumber != null)
            {
                _ShortItemNumber = _CollectItemNumber.ItemsTable.IMITM;
                _LongItemNumber = _CollectItemNumber.ItemsTable.IMLITM;
                _ThirdItemNumber = _CollectItemNumber.ItemsTable.IMAITM;

                ScreenHandler.ScreenMap.Add("ItemNumber", sItemNumber);

                // Retrieve Item Branch
                if (_CollectItemNumber.ItemBranchesTable.ValidateItemBranch(_Branch, _ShortItemNumber))
                {
                    _LotProcessType = _CollectItemNumber.ItemBranchesTable.IBSRCE;
                } // end if
                else
                {
                    _LotProcessType = "";
                } // end else

                bRetVal = true;
            }

            return (bRetVal);
        }

        #endregion

        #region SendToERP

        private void setItem()
        {
            _CycleCountTransaction.PrimaryItemNumber = _PrimaryItemNumber;
            switch (_CollectBranch.WarehouseConstantsTable._DesignatedPrimaryItemNumber)
            {
                case PrimaryItemNumberDesignations.ShortNumber:
                    _CycleCountTransaction.PrimaryItemNumber = _CollectItemNumber.ItemsTable.IMITM.ToString();
                    break;
                case PrimaryItemNumberDesignations.LongNumber:
                    _CycleCountTransaction.PrimaryItemNumber = _CollectItemNumber.ItemsTable.IMLITM;
                    break;
                case PrimaryItemNumberDesignations.ThirdNumber:
                    _CycleCountTransaction.PrimaryItemNumber = _CollectItemNumber.ItemsTable.IMAITM;
                    break;
            }

            _CycleCountTransaction.ShortItemNumber = _CollectItemNumber.ItemsTable.IMITM.ToString(); // short item number
            _CycleCountTransaction.SecondItemNumber = _CollectItemNumber.ItemsTable.IMLITM.ToString(); // 2nd item number
            _CycleCountTransaction.ThirdItemNumber = _CollectItemNumber.ItemsTable.IMAITM.ToString(); // 3rd item number
            _CycleCountTransaction.ItemDescription1 = _CollectItemNumber.ItemsTable.IMDSC1.Trim();
            _CycleCountTransaction.ItemDescription2 = _CollectItemNumber.ItemsTable.IMDSC2.Trim();

            _CollectItemNumber.ItemBranchesTable.ValidateItemBranch(_TableFormattedBranchPlant.Trim(), _CollectItemNumber.ItemsTable.IMITM);
            _CycleCountTransaction.ItemDimGroup = _CollectItemNumber.ItemBranchesTable.IBPRP6.Trim();
            _CycleCountTransaction.ItemLotProcType = _CollectItemNumber.ItemBranchesTable.IBSRCE;
        }

        private void setLocation()
        {
            _CycleCountTransaction.Location = _Location;
            if (_LocationMasterTable.ValidateLocation(_TableFormattedBranchPlant.Trim(), _Location))
            {
                _CycleCountTransaction.LocnPutZone = _LocationMasterTable.LMPZON.Trim();
                _CycleCountTransaction.LocnPickZone = _LocationMasterTable.LMKZON.Trim();
                _CycleCountTransaction.LocnReplZone = _LocationMasterTable.LMZONR.Trim();
                _CycleCountTransaction.LocnDimGroup = _LocationMasterTable.LMSTY1.Trim();
            }
        }

        private void SendToERP()
        {
            Log.Debug($"<***> SendToERP()");
            Transactions.Add(_CycleCountTransaction);

            Transactions.Branch = _TableFormattedBranchPlant.Trim().ToUpperInvariant();
            _CycleCountTransaction.Initialize();
            setLocation();
            setItem();
            _CycleCountTransaction.BranchPlant = _TableFormattedBranchPlant; // Branch
            _CycleCountTransaction.CycleCountNumber = _CycleCountNumber; // Count number
            _CycleCountTransaction.Lot = _LotNumber; // lot number
            _CycleCountTransaction.Quantity = _TransactionQuantity.ToString(); // quantity
            _CycleCountTransaction.UOM = _CollectItemNumber.ItemsTable.IMUOM1; // unit of measure
            _CycleCountTransaction.SecondaryQuantity = _DualQuantity.ToString();
            _CycleCountTransaction.SecondaryUOM = _DualUnitOfMeasure;
            _CycleCountTransaction.RFUserID = UserSession.CurrentUser.LoginName;
            _CycleCountTransaction.TransDate_YYYYMMDD = System.DateTime.Now.ToString("yyyyMMdd");
            _CycleCountTransaction.Version = WFOptions.RetrieveOptionValue("ERPUpdateVersion").ToString().Trim();
            _CycleCountTransaction.ReplaceQty = "1";
            _CycleCountTransaction.LicensePlateNumber = _LicensePlate;
            _CycleCountTransaction.UpdateF4141PJTQOH = WFOptions.RetrieveOptionValue("UpdateCountOnHandQuantity").ToString().ToUpper().Trim();
            _CycleCountTransaction.QuantityAtTimeOfCount = _ItemLocationTable.LIPQOH.ToString();
            Transactions.Send(WFOptions.RetrieveOptionValue("SyncTransaction").ToString());
            DisplayMessages();
            Log.Debug($"<***> Transaction {Transactions.Error}");

            if (!Transactions.Error)
            {
                Log.Debug($"<***> Post Transaction");
                switch (_CountType)
                {
                    case "5":
                        _PITagTable.UpdateTagScan(_Branch, _TagNumber, _CycleCountNumber, UserSession.CurrentUser.LoginName, _EnteredQty);
                        break;
                    case "6":
                        Log.Debug($"<***>UpdateTagScan _CycleCountNumber {_CycleCountNumber}, _TagNumber {_TagNumber} _EnteredQty {_EnteredQty}, _Location {_Location}");
                        _PITagTable.UpdateTagScan(_Branch, _TagNumber, _CycleCountNumber, UserSession.CurrentUser.LoginName, _EnteredQty, _Location);
                        break;
                }
            }

            UnlockCountRecord();
            _FromLicensePlate = false;
            _ThisCountType = _CountType;
            _LastLocationProcessed = _Location;
            /*_CycleCountNumber = _PreviousCycleCountNumber;
            CycleCountExists();*/
        }

        #endregion

        #region UpdateOfflineCount

        private void UpdateOfflineCount()
        {
            // if this is an added record, then we want
            // to stay on the initial record where the user
            // hit the "add" button

            if (!_AddedCountRecord)
            {
                //BD013894 - Check to make sure there is a row to set column at.
                if (_NextRecord < _CountLocationsTable.Rows.Count)
                {
                    _NextRecord += 1;
                }
            }
        }

