        private void DisplayLockInformation()
        {
            ScreenHandler.ScreenMap.Add("OrderNumber", _CycleCountDetailTable.PJCYNO.ToString());
            ScreenHandler.ScreenMap.Add("DocType", " ");
            ScreenHandler.ScreenMap.Add("LineNumber", " ");
            switch (_CollectBranch.WarehouseConstantsTable._DesignatedPrimaryItemNumber)
            {
                case PrimaryItemNumberDesignations.ShortNumber:
                    ScreenHandler.ScreenMap.Add("ItemNumber", _CycleCountDetailTable.PJITM.ToString());
                    break;
                case PrimaryItemNumberDesignations.LongNumber:
                    ScreenHandler.ScreenMap.Add("ItemNumber", _CycleCountDetailTable.PJLITM.ToString());
                    break;
                case PrimaryItemNumberDesignations.ThirdNumber:
                    ScreenHandler.ScreenMap.Add("ItemNumber", _CycleCountDetailTable.PJAITM.ToString());
                    break;
            }

            ScreenHandler.ScreenMap.Add("Description1", _CycleHeaderTable.PIDSC1.ToString());
            ScreenHandler.ScreenMap.Add("UserID", _ERPRecordLockTable.UserID.ToString());
            ScreenHandler.ScreenMap.Add("WorkflowID", _ERPRecordLockTable.WorkflowID.ToString());

            Next(_BusinessDataRecordLockDisplay);
