        private void DisplayLockInformation_ExitEvent(RFSScreenControl sender, ScreenEventArgs EventArgs)
        {
            Exit();
        }

        private void DisplayLockInformation_BackEvent(RFSScreenControl sender, ScreenEventArgs EventArgs)
        {
            Back();
        }

        #region DisplayLockInformation_KeyEvent

        private void DisplayLockInformation_KeyEvent(RFSScreenControl sender, ScreenEventArgs e)
        {
            switch (e.KeyPressed)
            {
                case ActionKey.F2: // user hits F2 - Skip To Location
                    if (_CountType == "4") // random count
                        RestartLoop(_CollectLocation);
                    else
                    {
                        _LocationBeforeF2 = _CycleCountDetailTable.PJLOCN.ToString();
                        _ThisCountType = _WorkflowOptionCountType.Random.ToString("D");
                        Next(_CollectSkipToLocation);
                    }

                    break;
                case ActionKey.Enter:
                    Back();
                    break;
                default:
                    Error("JDEWrongKey");
                    break;
            }
        }

