        #region CreateDataSet

        private void CreateDataSet()
        {
            _CountDetailDataSet = new DataSet("CountDetailDataSet");
            _CountLocationsTable = new DataTable("CountDetailTable");
            _CountLocationsTable.Columns.Add("Location");
            _CountDetailDataSet.Tables.Add(_CountLocationsTable);
        }

        #endregion

        #region LoadDataSet

        private void LoadDataSet(string TypeOfLoad, string From, string To)
        {
            _CountDetailDataSet.Clear();
            if (_CycleCountDetailTable.RetrieveNextCountRecordByLoadType(_TableFormattedBranchPlant, _CycleCountNumber,
                    TypeOfLoad, _TableFormattedFromLocation, _TableFormattedToLocation,
                    _LocationMasterTable.FormatLocationPrefix(_Branch, _LocationPrefix), _Location, _AllowRecount))
            {
                //Below code is as HUGE pain, but AS400 uses EBCDIC characters and 3 > A in EBCDIC
                if (TypeOfLoad == "FromTo")
                {
                    string filter = "PJLOCN >= '" + _TableFormattedFromLocation + "' AND PJLOCN <= '" + _TableFormattedToLocation + "' ";
                    _CycleCountDetailTable.ThisDataTable.DefaultView.RowFilter = filter;
                }

                foreach (DataRowView ccdrv in _CycleCountDetailTable.ThisDataTable.DefaultView)
                {
                    DataRow dr = _CountDetailDataSet.Tables["CountDetailTable"].NewRow();
                    dr["Location"] = ccdrv["PJLOCN"].ToString(); //_CycleCountDetailTable["PJLOCN"].ToString();

                    _CountLocationsTable.Rows.Add(dr);
                }
            }

            _NextRecord = -1;
        }

        #endregion

        #region LocationHasLicensePlates

        /// <summary>
        /// Checks to see if there are any licenses plates to count for the given Cycle Count, Branch
        /// Plant, Short Item Number, Location, and Location combination.  If there are, the _bLPCounting
        /// flag is set indicating that the user should stay in the License Plate count loop until all
        /// License Plates have been counted or the user does not feel like continuing.
        /// </summary>
        /// <returns>Returns true if License Plating is enabled and there are License Plates to
        /// count; otherwise, false.</returns>
        private bool LocationHasLicensePlates()
        {
            bool bRetVal = false;

            ScreenHandler.ScreenMap.Add("CCQTYLBL", "Loose Qty");
            _bLPCounting = false; // There are no more License Plates to Count.  End LP counting.

            return (bRetVal);
        }

